12	func writeRawLog(t *testing.T, dir string, data []byte) string {
13		t.Helper()
14		path := filepath.Join(dir, logName)
15		if err := os.WriteFile(path, data, 0o600); err != nil {
16			t.Fatal(err)
17		}
