21	// assertCorruptAndUntouched opens dir, requires ErrCorrupt with no usable
22	// queue, and requires queue.log to remain byte-for-byte as written.
23	func assertCorruptAndUntouched(t *testing.T, dir string, want []byte) {
24		t.Helper()
25		path := filepath.Join(dir, logName)
26		q, err := Open(dir)
27		if !errors.Is(err, ErrCorrupt) {
28			if q != nil {
29				q.Close()
30			}
31			t.Fatalf("want ErrCorrupt, got %v (queue=%v)", err, q != nil)
32		}
33		if q != nil {
34			q.Close()
35			t.Fatalf("corrupt open must not return a usable queue")
36		}
37		got, rerr := os.ReadFile(path)
38		if rerr != nil {
39			t.Fatal(rerr)
40		}
41		if string(got) != string(want) {
42			t.Fatalf("corrupt log was modified: want %d bytes, got %d bytes", len(want), len(got))
43		}
44	}
