46	// A log that contains the magic but no intact, checksum-valid, supported
47	// version record as its first record must be rejected as corrupt on the very
48	// first open, never truncated down to a magic-only shell that later appends
49	// could turn into a headerless log. None of these failures may alter the
50	// file, and a repeated open must keep failing rather than replacing the log.
51	func TestHeadVersionRecordMustBeIntact(t *testing.T) {
52		versionFrame := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))
53	
54		cases := map[string][]byte{
55			"magic only": []byte(logMagic),
56			// One to three of the four length bytes survived.
57			"one length byte":    append([]byte(logMagic), versionFrame[:1]...),
58			"two length bytes":   append([]byte(logMagic), versionFrame[:2]...),
59			"three length bytes": append([]byte(logMagic), versionFrame[:3]...),
60			// Full length saved but body/checksum missing or cut short.
61			"length without body":    append([]byte(logMagic), versionFrame[:frameHeaderSize]...),
62			"partial body":           append([]byte(logMagic), versionFrame[:frameHeaderSize+2]...),
63			"body without crc":       append([]byte(logMagic), versionFrame[:len(versionFrame)-frameCRCsSize]...),
64			"frame missing one crc":  append([]byte(logMagic), versionFrame[:len(versionFrame)-1]...),
65			"complete frame bad crc": append(append([]byte(logMagic), versionFrame[:len(versionFrame)-1]...), versionFrame[len(versionFrame)-1]^0xFF),
66		}
67		// A complete frame whose payload byte is flipped fails its checksum while
68		// sitting exactly at EOF.
69		badBody := append([]byte(nil), versionFrame...)
70		badBody[frameHeaderSize+2] ^= 0xFF
71		cases["complete frame bad body"] = append([]byte(logMagic), badBody...)
72		// A complete, checksum-valid first record that is not a version record.
73		cases["first record is source"] = append([]byte(logMagic),
74			encodeFrame(mustMarshal(&logEntry{T: kindSource, Chain: "a"}))...)
75		// A complete version record naming an unsupported version.
76		cases["unsupported version"] = append([]byte(logMagic),
77			encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV + 1}))...)
78	
79		for name, data := range cases {
80			t.Run(name, func(t *testing.T) {
81				dir := t.TempDir()
82				writeRawLog(t, dir, data)
83	
84				assertCorruptAndUntouched(t, dir, data)
85	
86				// A corrupt head must not be auto-replaced with a fresh log on a
87				// later open: the user's bytes stay in place for diagnosis.
88				assertCorruptAndUntouched(t, dir, data)
89	
90				// No stray replacement or temp log was written beside the original.
91				entries, err := os.ReadDir(dir)
92				if err != nil {
93					t.Fatal(err)
94				}
95				for _, e := range entries {
96					if e.Name() != logName && e.Name() != "lock" {
97						t.Fatalf("failed open left unexpected file %q", e.Name())
98					}
99				}
100			})
101		}
102	}
103	
104	// Directories with no queue.log at all (never created, or just created) still
105	// initialize a fresh queue normally — they are distinct from an existing but
106	// incomplete magic-only log, which is corrupt data and must not be replaced.
107	func TestAbsentLogStillInitializes(t *testing.T) {
108		for name, setup := range map[string]func(t *testing.T) string{
109			"nonexistent dir": func(t *testing.T) string {
110				return filepath.Join(t.TempDir(), "nested", "queue-state")
111			},
112			"empty dir": func(t *testing.T) string {
113				return t.TempDir()
114			},
115		} {
116			t.Run(name, func(t *testing.T) {
117				dir := setup(t)
118				q, err := Open(dir)
119				if err != nil {
120					t.Fatalf("fresh directory must initialize: %v", err)
121				}
122				if err := q.RegisterSource("a"); err != nil {
123					t.Fatal(err)
124				}
125				if err := q.Close(); err != nil {
126					t.Fatal(err)
127				}
128				// Reopen restores the registered source.
129				q2, err := Open(dir)
130				if err != nil {
131					t.Fatalf("reopen fresh queue: %v", err)
132				}
133				defer q2.Close()
134				if !q2.sources["a"] {
135					t.Fatal("registered source not persisted")
136				}
137			})
138		}
