148	// With an intact leading version record, torn-tail recovery keeps working
149	// exactly as before: the acknowledged prefix is restored and the queue stays
150	// usable, whether the last record is partial or complete-but-bad-CRC.
151	func TestValidVersionPreservesTailRecovery(t *testing.T) {
152		dir := t.TempDir()
153		q, err := Open(dir)
154		if err != nil {
155			t.Fatal(err)
156		}
157		if err := q.RegisterSource("a"); err != nil {
158			t.Fatal(err)
159		}
