164			t.Fatal(err)
165		}
166		if _, err := q.Advance(1000); err != nil {
167			t.Fatal(err)
168		}
169		m2 := encodeFrame(mustMarshal(&logEntry{
170			T: kindSubmit, Seq: 1, ID: "m2", From: "a", To: "b", Nonce: 2, ProofAt: 10,
171		}))
172		if err := q.Close(); err != nil {
173			t.Fatal(err)
174		}
