176		raw, err := os.ReadFile(filepath.Join(dir, logName))
177		if err != nil {
178			t.Fatal(err)
179		}
180		base := append([]byte(nil), raw...)
181	
182		t.Run("partial final record", func(t *testing.T) {
183			d := t.TempDir()
184			torn := append(base[:len(base):len(base)], m2[:len(m2)-3]...)
185			writeRawLog(t, d, torn)
