206	// assertRecoveredPrefixUsable verifies the acknowledged prefix (source a,
207	// delivered m1) is restored, the dropped final submit for missingID never
208	// existed, and the reopened queue accepts new operations.
209	func assertRecoveredPrefixUsable(t *testing.T, q *Queue, missingID string) {
210		t.Helper()
