213			t.Fatal("acknowledged source registration lost")
214		}
215		if r := statusOf(t, q, "m1"); r.Status != StatusSuccess {
216			t.Fatalf("acknowledged success lost: %+v", r)
217		}
218		if winner := q.consumed[newConsumeToken("a", "b", 1)]; winner != "m1" {
219			t.Fatalf("consumed nonce not restored: %q", winner)
220		}
221		if _, ok := q.Query(missingID); ok {
